mapper.select:
SELECT o.order_no, o.member_id, m.member_name, o.order_state, o.total_amount, o.ordered_at
  FROM ORDERS o
  JOIN MEMBERS m ON o.member_id = m.member_id
 WHERE o.del_yn = 'N'

   AND o.ordered_at >= #{startDate}


   AND o.ordered_at < #{endDate} + INTERVAL 1 DAY


   AND o.member_id = #{memberId}


   AND o.order_state = #{state}

 ORDER BY o.ordered_at DESC
 LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
  FROM ORDERS o
 WHERE o.del_yn = 'N'

   AND o.ordered_at >= #{startDate}


   AND o.ordered_at < #{endDate} + INTERVAL 1 DAY


   AND o.member_id = #{memberId}


   AND o.order_state = #{state}

SELECT o.order_no, o.order_state, o.total_amount, o.ordered_at
  FROM ORDERS o
 WHERE o.del_yn = 'N'
   AND o.member_id = #{memberId}
 ORDER BY o.ordered_at DESC, o.order_no DESC
 LIMIT #{limit}

SELECT t.order_no, t.delivery_state FROM ( SELECT d.order_no, d.delivery_state, ROW_NUMBER() OVER (PARTITION BY d.order_no ORDER BY d.delivery_no DESC) AS rn FROM ORDER_DELIVERY d WHERE d.order_no IN
#{orderNo}
) t WHERE t.rn = 1

mapper.update:
UPDATE ORDERS
   SET order_state = #{state}
 WHERE order_no = #{orderNo}
   AND del_yn = 'N'
   AND order_state NOT IN ('CANCELED', 'DONE')
